Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
Little Petya loves training spiders. Petya has a board n × m in size. Each cell of the board initially has a spider sitting on it. After one second Petya chooses a certain action for each spider, and all of them humbly perform its commands. There are 5 possible commands: to stay idle or to move from current cell to some of the four side-neighboring cells (that is, one command for each of the four possible directions). Petya gives the commands so that no spider leaves the field. It is allowed for spiders to pass through each other when they crawl towards each other in opposite directions. All spiders crawl simultaneously and several spiders may end up in one cell. Petya wants to know the maximum possible number of spider-free cells after one second.
</problem_description>

Here is the Java 6 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class ProblemE {
    private static int C, R;
    private static final int MAX_VAL = 9999999;
    private static Set<Integer> variations = new HashSet<Integer>();

    private static void exploreAll(int index, int depth, int config) {
        if (index >= C) {
            variations.add(config);
            return;
        }
        if (depth >= 1) {
            exploreAll(index+1, depth, config|(1<<index));
        }
        if (depth <= R - 2) {
            exploreAll(index+1, depth, config|(1<<(index+C*2)));
        }
        if (index >= 1) {
            exploreAll(index+1, depth, config|(1<<((index-1)+C)));
        }
        if (index <= C - 2) {
            exploreAll(index+1, depth, config|(1<<((index+1)+C)));
        }
        exploreAll(index+1, depth, config|(1<<(index+C)));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().trim().split("\\s+");
        C = Integer.parseInt(data[0]);
        R = Integer.parseInt(data[1]);
        if (C > R) {
            int temp = C;
            C = R;
            R = temp;
        }

        int[][] memoTable = new int[R+1][1<<(C*3)];
        for (int row = 0 ; row <= R ; row++) {
            Arrays.fill(memoTable[row], MAX_VAL);
        }
        memoTable[0][0] = 0;

        for (int level = 0 ; level < R ; level++) {
            variations.clear();
            exploreAll(0, level, 0);
            for (int state = 0 ; state < 1<<(C*2) ; state++) {
                if (memoTable[level][state] != MAX_VAL) {
                    for (int variation : variations) {
                        int merged = (variation | state);
                        int nextState = merged >> C;
                        int added = Integer.bitCount(merged & ((1<<C) - 1));
                        memoTable[level+1][nextState] = Math.min(memoTable[level+1][nextState], memoTable[level][state] + added);
                    }
                }
            }
        }

        int minimum = MAX_VAL;
        for (int finalState = 0 ; finalState < 1<<(C*2) ; finalState++) {
            minimum = Math.min(minimum, memoTable[R][finalState] + Integer.bitCount(finalState));
        }
        System.out.println(R * C - minimum);
    }
}
</original_code>
